dict(id='freelancer-ranges',topic='Print-on-demand',bot=M,title='Price your services from real market ranges',
 do='Before setting a price for design or setup work, look at what freelancers charge right now.',
 why='Live freelancer pages give you real low, typical and premium ranges to compare against, with links you can show a client. One big site blocked our bot, so check more than one.'),
# Website
dict(id='one-list',topic='Your website',bot=X,title='Keep one list of your sites, and let it win',
 do='Pick one page that lists every site you run, and start every check from it.',
 why='Our site counts drifted from note to note until every check started from one list of 83 sites.',build='subdomain-audit'),
dict(id='checkable',topic='Your website',bot=X,title='Every fact on your site should be checkable',
 do='Name who said each quote and where, trace every date and figure to a source, credit every image, and cut any claim you cannot source.',
 why='Readers need to tell a checked fact from a joke. Our sites keep their misses on the page too.'),
dict(id='one-index',topic='Your website',bot=X,title='Make all your sites searchable in one place',
 do='Collect the text of every site into one searchable index, and search it before writing anything new.',
 why='Facts were spread across many sites. Searching first stops new pages from repeating or contradicting old ones.'),
dict(id='kids-checklist',topic='Your website',bot=X,title='Give anything for kids its own stricter checklist',
 do='Write a separate checklist for kids pages and videos: facts checked from the live page, round honest numbers, every on-screen word spoken aloud, a safety line on try-it moments.',
 why='Kids content needs a different standard. Every kids video is checked against one list and opens on a card that reads "For curious kids, with a grown-up close by."'),
dict(id='shared-footer',topic='Your website',bot=X,title='Share one footer across your sites',
 do='Keep the footer in one shared file that every site reads, then check which sites really read it.',
 why='Each site had its own copy, so a new site meant editing dozens by hand. Checking showed some sites still used an old copy.'),
dict(id='audit-batches',topic='Your website',bot=X,title='Check every site at once, then fix in small batches',
 do='Run one check across all your sites, then fix the worst and oldest first, a few at a time.',
 why='A site that is up can still have dead links, broken share previews and layout slips. One check across every site finds them all at once.'),
dict(id='write-rules',topic='Your website',bot=X,title='Write your design rules down so a bot can check them',
 do='Turn "it looks off" into rules you can measure, like "every block lines up on the same edges within 4 pixels."',
 why='Once the rules are written with numbers, the check can flag layout problems on its own.'),
dict(id='page-loads',topic='Your website',bot=T,title='A page can load and still be broken',
 do='Check what a page shows, not just that it loads. Test each style and script file twice, a few minutes apart.',
 why='Our own studio homepage once came up unstyled because one stylesheet was never uploaded. Now every build fails if a page links a file that is not there.',img=['from-metis/img/pr10-live-home-1440.png']),
dict(id='check-what-linked',topic='Your website',bot=T,title='Make your checks look at what the page links',
 do='Have the check fail if a page has no stylesheet at all, and check images and icons too, not only that some file exists.',
 why='A check that only asks "does this file exist?" can pass while the page is missing its styling.'),
dict(id='crops',topic='Your website',bot=T,title='Keep everything on one edge, and check photo crops at real sizes',
 do='Look at the page on a phone and a big screen and measure that blocks share the same left and right edges.',
 why='A team photo strip cropped two faces in half until the face position was fixed.',img=['from-metis/img/pr9-strip-before.png','from-metis/img/pr9-strip-after.png']),
dict(id='live-render',topic='Your website',bot=T,title='Only the live page counts',
 do='After every change, open the published page and look. Code that looks right is not proof.',
 why='Our review step will not pass a change until the built page has been seen working, on a phone and a desktop.'),
dict(id='not-same-settings',topic='Your website',bot=X,title="Don't assume every site has the same settings",
 do='Check each site for the settings you care about, like whether it asks to be left out of search.',
 why='All our sites ask search engines not to list them except one.',build='subdomain-audit'),
dict(id='contact',topic='Your website',bot=X,title='Every site needs a way to reach you',
 do='Put a contact line in your shared footer so every site gets it.',
 why='A check found a contact address on only some of our sites.'),
dict(id='readable-text',topic='Your website',bot=X,title='Make text big, light and on a dark box',
 do='Use white or ivory text, about 8% of the frame height, on a soft dark box. Keep gold for decoration only.',
 why='Gold captions over video were unreadable. The new standard is in our video checklist.',img=['desk/ops/canva-threshold-before-fix.png','desk/ops/canva-threshold-text-fixed-preview.png']),
dict(id='install-icons',topic='Your website',bot=T,title='Give each site its own icons if people save it to their phone',
 do='Add a proper app icon set and start screens, then check each file is the exact size.',
 why='Most of our sites used the default. In a small pilot the code passed, but some icon art needed redoing.'),
# X
